from __future__ import annotations

import base64
import html
import io
import json

from PIL import Image

BBOX_EDITOR_CSS = """
.bbox-editor-shell {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}
.bbox-editor-canvas {
  display: block;
  max-width: 100%;
  height: auto;
  border: 1px solid #d1d5db;
  border-radius: 4px;
  touch-action: none;
  user-select: none;
  -webkit-user-drag: none;
  background: #111827;
}
.bbox-editor-hint {
  color: #374151;
  font-size: 14px;
}
"""

BBOX_EDITOR_JS = r"""
const bindEditor = () => {
  const shell = element.querySelector(".bbox-editor-shell");
  const canvas = element.querySelector(".bbox-editor-canvas");
  if (!shell || !canvas || canvas.dataset.bound === "true") return;
  canvas.dataset.bound = "true";
  const ctx = canvas.getContext("2d");
  const cfg = JSON.parse(shell.dataset.config);
  const image = new Image();
  let box = cfg.bbox ? cfg.bbox.slice() : null;
  let firstCorner = null;
  let drag = null;
  let moved = false;
  const handleRadius = 8;
  const hitRadius = 14;

  const clamp = (value, low, high) => Math.max(low, Math.min(high, value));
  const pointer = (evt) => {
    const rect = canvas.getBoundingClientRect();
    return [
      (evt.clientX - rect.left) * canvas.width / rect.width,
      (evt.clientY - rect.top) * canvas.height / rect.height,
    ];
  };
  const toOriginalBox = (value) => [
    Math.round(value[0] * cfg.originalWidth / canvas.width),
    Math.round(value[1] * cfg.originalHeight / canvas.height),
    Math.round(value[2] * cfg.originalWidth / canvas.width),
    Math.round(value[3] * cfg.originalHeight / canvas.height),
  ];
  const toOriginalPoint = (value) => [
    Math.round(value[0] * cfg.originalWidth / canvas.width),
    Math.round(value[1] * cfg.originalHeight / canvas.height),
  ];
  const handles = (value) => {
    const [x1, y1, x2, y2] = value;
    const cx = (x1 + x2) / 2;
    const cy = (y1 + y2) / 2;
    return {
      nw: [x1, y1], n: [cx, y1], ne: [x2, y1], e: [x2, cy],
      se: [x2, y2], s: [cx, y2], sw: [x1, y2], w: [x1, cy],
    };
  };
  const hitTest = (point) => {
    if (!box) return null;
    for (const [name, value] of Object.entries(handles(box))) {
      if (Math.hypot(point[0] - value[0], point[1] - value[1]) <= hitRadius) {
        return name;
      }
    }
    if (
      point[0] >= box[0] && point[0] <= box[2] &&
      point[1] >= box[1] && point[1] <= box[3]
    ) return "move";
    return null;
  };
  const drawCross = (point, color) => {
    if (!point) return;
    ctx.strokeStyle = "white";
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(point[0], point[1], 10, 0, Math.PI * 2);
    ctx.stroke();
    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(point[0], point[1], 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(point[0] - 15, point[1]);
    ctx.lineTo(point[0] + 15, point[1]);
    ctx.moveTo(point[0], point[1] - 15);
    ctx.lineTo(point[0], point[1] + 15);
    ctx.stroke();
  };
  const draw = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
    if (box) {
      const color = cfg.candidate ? "#f5b700" : "#00d26a";
      ctx.strokeStyle = color;
      ctx.lineWidth = 3;
      ctx.strokeRect(box[0], box[1], box[2] - box[0], box[3] - box[1]);
      if (cfg.mode === "bbox") {
        for (const value of Object.values(handles(box))) {
          ctx.fillStyle = "white";
          ctx.strokeStyle = color;
          ctx.lineWidth = 3;
          ctx.beginPath();
          ctx.arc(value[0], value[1], handleRadius, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();
        }
      }
    }
    if (firstCorner) drawCross(firstCorner, "#f5b700");
    if (cfg.contact) drawCross(cfg.contact, cfg.contactCandidate ? "#ff2d9a" : "#00dfff");
  };
  const resize = (point) => {
    const start = drag.startBox;
    let [x1, y1, x2, y2] = start;
    const name = drag.kind;
    if (name === "move") {
      const dx = point[0] - drag.startPoint[0];
      const dy = point[1] - drag.startPoint[1];
      const width = x2 - x1;
      const height = y2 - y1;
      x1 = clamp(x1 + dx, 0, canvas.width - width);
      y1 = clamp(y1 + dy, 0, canvas.height - height);
      x2 = x1 + width;
      y2 = y1 + height;
    } else {
      if (name.includes("w")) x1 = clamp(point[0], 0, x2 - 8);
      if (name.includes("e")) x2 = clamp(point[0], x1 + 8, canvas.width);
      if (name.includes("n")) y1 = clamp(point[1], 0, y2 - 8);
      if (name.includes("s")) y2 = clamp(point[1], y1 + 8, canvas.height);
    }
    box = [x1, y1, x2, y2];
  };

  image.onload = () => {
    canvas.width = cfg.displayWidth;
    canvas.height = cfg.displayHeight;
    draw();
  };
  image.src = cfg.image;

  canvas.addEventListener("pointerdown", (evt) => {
    evt.preventDefault();
    canvas.setPointerCapture(evt.pointerId);
    const point = pointer(evt);
    moved = false;
    if (cfg.mode === "contact") {
      drag = {kind: "contact", startPoint: point};
      return;
    }
    const kind = hitTest(point);
    if (kind) {
      drag = {kind, startPoint: point, startBox: box.slice()};
      return;
    }
    drag = {kind: "new", startPoint: point};
  });
  canvas.addEventListener("pointermove", (evt) => {
    if (!drag) return;
    evt.preventDefault();
    const point = pointer(evt);
    moved = moved || Math.hypot(
      point[0] - drag.startPoint[0],
      point[1] - drag.startPoint[1],
    ) > 2;
    if (drag.kind !== "new" && drag.kind !== "contact") {
      resize(point);
      draw();
    }
  });
  canvas.addEventListener("pointerup", (evt) => {
    if (!drag) return;
    evt.preventDefault();
    const point = pointer(evt);
    if (drag.kind === "contact") {
      trigger("apply", {action: "contact", point: toOriginalPoint(point)});
    } else if (drag.kind === "new" && !moved) {
      if (!firstCorner) {
        firstCorner = point;
        draw();
      } else {
        box = [
          Math.min(firstCorner[0], point[0]),
          Math.min(firstCorner[1], point[1]),
          Math.max(firstCorner[0], point[0]),
          Math.max(firstCorner[1], point[1]),
        ];
        firstCorner = null;
        draw();
        trigger("apply", {action: "bbox", bbox: toOriginalBox(box)});
      }
    } else if (drag.kind === "move" && !moved) {
      trigger("apply", {action: "contact", point: toOriginalPoint(point)});
    } else if (drag.kind !== "new") {
      trigger("apply", {action: "bbox", bbox: toOriginalBox(box)});
    }
    drag = null;
  });
  canvas.addEventListener("pointercancel", () => { drag = null; });
};
bindEditor();
watch("value", () => setTimeout(bindEditor, 0));
"""


def _image_data_uri(image: Image.Image) -> str:
    buffer = io.BytesIO()
    image.save(buffer, format="JPEG", quality=88)
    encoded = base64.b64encode(buffer.getvalue()).decode("ascii")
    return f"data:image/jpeg;base64,{encoded}"


def render_bbox_editor(
    image: Image.Image,
    *,
    original_size: tuple[int, int],
    mode: str,
    bbox: list[float] | tuple[float, ...] | None,
    bbox_is_candidate: bool,
    contact: list[float] | tuple[float, ...] | None,
    contact_is_candidate: bool,
) -> str:
    display_width, display_height = image.size
    original_width, original_height = original_size
    display_bbox = None
    if bbox:
        display_bbox = [
            float(bbox[0]) * display_width / original_width,
            float(bbox[1]) * display_height / original_height,
            float(bbox[2]) * display_width / original_width,
            float(bbox[3]) * display_height / original_height,
        ]
    display_contact = None
    if contact:
        display_contact = [
            float(contact[0]) * display_width / original_width,
            float(contact[1]) * display_height / original_height,
        ]
    config = {
        "image": _image_data_uri(image),
        "displayWidth": display_width,
        "displayHeight": display_height,
        "originalWidth": original_width,
        "originalHeight": original_height,
        "mode": mode,
        "bbox": display_bbox,
        "candidate": bbox_is_candidate,
        "contact": display_contact,
        "contactCandidate": contact_is_candidate,
    }
    encoded_config = html.escape(
        json.dumps(config, separators=(",", ":")),
        quote=True,
    )
    hint = (
        "先点击两个角画框；框内轻点可标接触点，按住拖动才移动框；四角和四边可缩放。"
        if mode == "bbox"
        else "点击治疗头最接近皮肤位置的中心点；返回框模式后仍可继续调整设备框。"
    )
    return (
        f'<div class="bbox-editor-shell" data-config="{encoded_config}">'
        '<canvas class="bbox-editor-canvas"></canvas>'
        f'<div class="bbox-editor-hint">{hint}</div>'
        "</div>"
    )

