from src import contact_annotations as contacts
from src.bbox_annotations import (
    BBox,
    interpolate_records,
    load_records as load_bbox_records,
    propagate_exact_duplicates as propagate_bbox_duplicates,
    read_rgb,
    record_bbox,
    save_records as save_bbox_records,
    set_device,
    set_no_device,
    set_pending as set_bbox_pending,
    summary as bbox_summary,
    write_metadata as write_bbox_metadata,
)
from src.bbox_editor import BBOX_EDITOR_CSS, BBOX_EDITOR_JS, render_bbox_editor
from src.pilot_dataset import P0_OBSERVE_IDS, P1_EXTRA_IDS, P1_SUPPLEMENTAL_IDS, P2_EXTRA_IDS
from src.pilot_queue import adjacent_index, first_unfinished, indices_for_numeric_ids, is_finished
from src.dataset_v2_split import queue_numeric_ids
from src.model_suggestions import read_suggestions, suggested_bbox, suggested_contact

PROJECT_ROOT = Path(__file__).resolve().parent
HOST = "127.0.0.1"
PORTS = (7860, 7861)
MAX_DISPLAY = (900, 780)
VIEW_LABELS = {
    "unknown": "未知/待确认",
    "front": "正面",
    "subject_left": "被拍摄者左侧",
    "subject_right": "被拍摄者右侧",
    "product": "设备展示图",
}
LABEL_TO_VIEW = {label: key for key, label in VIEW_LABELS.items()}
VISIBILITY_LABELS = {
    "visible": "清晰可见",
    "occluded_inferable": "遮挡但可可靠推断（需要复查）",
}
LABEL_TO_VISIBILITY = {label: key for key, label in VISIBILITY_LABELS.items()}
PILOT_P1_IDS = tuple(dict.fromkeys((*P0_OBSERVE_IDS, *P1_EXTRA_IDS, *P1_SUPPLEMENTAL_IDS)))
PILOT_P2_IDS = P2_EXTRA_IDS


def _dataset_v2_ids() -> tuple[int, ...]:
    try:
        return queue_numeric_ids(PROJECT_ROOT)
    except FileNotFoundError:
        return ()


def choose_port() -> int:
    for port in PORTS:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
            if sock.connect_ex((HOST, port)) != 0:
                return port
    raise RuntimeError("7860 和 7861 均被占用")


def _display_size(image: Image.Image) -> tuple[int, int]:
    scale = min(MAX_DISPLAY[0] / image.width, MAX_DISPLAY[1] / image.height, 1.0)
    return max(1, round(image.width * scale)), max(1, round(image.height * scale))


def _map_to_original(x: float, y: float, state: dict[str, object]) -> tuple[int, int]:
    dw, dh = state["display_size"]
    ow, oh = state["original_size"]
    return round(float(x) * ow / max(dw, 1)), round(float(y) * oh / max(dh, 1))


def _mode_for(index: int, bbox_records: list[dict[str, str]]) -> str:
    bbox = bbox_records[index]
    if bbox["review_state"] == "confirmed" and bbox["status"] == "device":
        return "contact"
    return "bbox"


def _next_unfinished(
    bbox_records: list[dict[str, str]],
    contact_records: list[dict[str, str]],
    start: int,
) -> int:
    return contacts.first_unfinished_index(bbox_records, contact_records, start)


def _active_indices(bbox_records: list[dict[str, str]], state: dict[str, object]) -> list[int]:
    queue_mode = state.get("queue_mode", "dataset_v2")
    if queue_mode == "dataset_v2":
        ids = _dataset_v2_ids()
        if ids:
            return indices_for_numeric_ids(bbox_records, ids)
    if queue_mode == "pilot_p2":
        return indices_for_numeric_ids(bbox_records, PILOT_P2_IDS)
    if queue_mode == "pilot_p1":
        return indices_for_numeric_ids(bbox_records, PILOT_P1_IDS)
    return list(range(len(bbox_records)))


def _next_active_unfinished(
    bbox_records: list[dict[str, str]],
    contact_records: list[dict[str, str]],
    state: dict[str, object],
    start: int,
) -> int:
    return first_unfinished(bbox_records, contact_records, _active_indices(bbox_records, state), start)


def _nearest_previous_box(records: list[dict[str, str]], index: int) -> BBox | None:
    sequence = records[index]["sequence_group"]
    for candidate in range(index - 1, -1, -1):
        if records[candidate]["sequence_group"] != sequence:
            break
        bbox = record_bbox(records[candidate])
        if bbox is not None and records[candidate]["review_state"] == "confirmed":
            return bbox
    return None


def initial_state() -> dict[str, object]:
    bbox_records = load_bbox_records(PROJECT_ROOT)
    if not contacts.annotation_path(PROJECT_ROOT).is_file():
        contact_records = contacts.initialize_records(PROJECT_ROOT)
    else:
        contact_records = contacts.load_records(PROJECT_ROOT)
    dataset_v2_ids = _dataset_v2_ids()
    queue_mode = "dataset_v2" if dataset_v2_ids else "pilot_p2"
    active = (
        indices_for_numeric_ids(bbox_records, dataset_v2_ids)
        if dataset_v2_ids
        else indices_for_numeric_ids(bbox_records, PILOT_P2_IDS)
    )
    index = first_unfinished(bbox_records, contact_records, active)
    return {
        "queue_mode": queue_mode,
        "index": index,
        "mode": _mode_for(index, bbox_records),
        "first_corner": None,
        "candidate_bbox": None,
        "candidate_contact": None,
        "anchor_index": None,
        "original_size": (1, 1),
        "display_size": (1, 1),
    }


def _render(
    bbox_records: list[dict[str, str]],
    contact_records: list[dict[str, str]],
    state: dict[str, object],
) -> Image.Image:
    index = int(state["index"])
    image = read_rgb(PROJECT_ROOT, bbox_records[index])
    display_size = _display_size(image)
    state["original_size"] = image.size
    state["display_size"] = display_size
    shown = image.resize(display_size, Image.Resampling.LANCZOS)
    draw = ImageDraw.Draw(shown)
    bbox_values = state.get("candidate_bbox")
    if bbox_values is None:
        bbox = record_bbox(bbox_records[index])
        bbox_values = bbox.as_list() if bbox else None
    if bbox_values:
        ow, oh = image.size
        dw, dh = display_size
        x1, y1, x2, y2 = bbox_values
        color = "#00d26a" if bbox_records[index]["review_state"] == "confirmed" else "#ffb000"
        draw.rectangle((x1 * dw / ow, y1 * dh / oh, x2 * dw / ow, y2 * dh / oh), outline=color, width=5)
    corner = state.get("first_corner")
    if corner:
        ow, oh = image.size
        dw, dh = display_size
        px, py = corner[0] * dw / ow, corner[1] * dh / oh
        draw.ellipse((px - 7, py - 7, px + 7, py + 7), fill="#00d26a", outline="white", width=2)
    point = state.get("candidate_contact") or contacts.contact_point(contact_records[index])
    if point:
        ow, oh = image.size
        dw, dh = display_size
        px, py = point[0] * dw / ow, point[1] * dh / oh
        color = "#ff2d9a" if state.get("candidate_contact") else "#00dfff"
        radius = 9
        draw.ellipse((px - radius, py - radius, px + radius, py + radius), outline="white", fill=color, width=2)
        draw.line((px - 15, py, px + 15, py), fill="white", width=2)
        draw.line((px, py - 15, px, py + 15), fill="white", width=2)
    return shown



def _editor_html(
    bbox_records: list[dict[str, str]],
    contact_records: list[dict[str, str]],
    state: dict[str, object],
) -> str:
    index = int(state["index"])
    image = read_rgb(PROJECT_ROOT, bbox_records[index])
    display_size = _display_size(image)
    state["original_size"] = image.size
    state["display_size"] = display_size
    shown = image.resize(display_size, Image.Resampling.LANCZOS)
    suggestion = read_suggestions(PROJECT_ROOT).get(bbox_records[index]["filename"])
    saved_bbox = record_bbox(bbox_records[index])
    candidate_bbox = state.get("candidate_bbox")
    model_bbox = suggested_bbox(suggestion) if saved_bbox is None else None
    bbox_values = candidate_bbox or (saved_bbox.as_list() if saved_bbox else model_bbox)
    saved_contact = contacts.contact_point(contact_records[index])
    candidate_contact = state.get("candidate_contact")
    model_contact = suggested_contact(suggestion) if saved_contact is None else None
    contact_values = candidate_contact or saved_contact or model_contact
    return render_bbox_editor(
        shown,
        original_size=image.size,
        mode=str(state["mode"]),
        bbox=bbox_values,
        bbox_is_candidate=candidate_bbox is not None or model_bbox is not None,
        contact=contact_values,
        contact_is_candidate=candidate_contact is not None or model_contact is not None,
    )

def _progress(
    bbox_records: list[dict[str, str]],
    contact_records: list[dict[str, str]],
    state: dict[str, object],
) -> str:
    index = int(state["index"])
    bbox_counts = bbox_summary(bbox_records)
    contact_counts = contacts.summary(contact_records)
    active = _active_indices(bbox_records, state)
    queue_finished = sum(is_finished(bbox_records, contact_records, value) for value in active)
    queue_name = {"pilot_p2": "P2 困难样本队列", "pilot_p1": "P1 试验队列"}.get(state.get("queue_mode"), "全部图片")
    bbox = bbox_records[index]
    contact = contact_records[index]
    return (
        f"### 当前队列：{queue_name}，已完成 {queue_finished}/{len(active)}\n"
        f"### 全部数据：设备框已确认 {bbox_counts['confirmed']}/{bbox_counts['total']}　"
        f"接触点已确认 {contact_counts['confirmed']}/{contact_counts['total']}\n"
        f"当前：**{index + 1}/{bbox_counts['total']} · {bbox['filename']}**　"
        f"模式：{state['mode']}　bbox：{bbox['status']}/{bbox['review_state']}　"
        f"接触点：{contact['contact_visibility']}/{contact['review_state']}"
    )

def _instructions(state: dict[str, object]) -> str:
    if state["mode"] == "contact":
        return (
            "### 步骤 2：标治疗头接触位置\n"
            "点击**设备治疗头前端最接近皮肤位置的中心点**。黑色圆形后端通常不是接触点。"
            "如果被手完全挡住、无法可靠判断，请不要猜，点击“无法可靠判断并下一张”。"
        )
    return (
        "### 步骤 1：标设备框\n"
        "依次点击所有可见设备的左上角和右下角，再保存设备框。"
        "框内不可避免包含手或脸是正常的；保存后仍停留在本图进入接触点步骤。"
    )


def _outputs(
    bbox_records: list[dict[str, str]],
    contact_records: list[dict[str, str]],
    state: dict[str, object],
    message: str = "",
):
    index = int(state["index"])
    bbox = record_bbox(bbox_records[index])
    suggestion = read_suggestions(PROJECT_ROOT).get(bbox_records[index]["filename"])
    bbox_values = (
        state.get("candidate_bbox")
        or (bbox.as_list() if bbox else suggested_bbox(suggestion))
