        or suggested_contact(suggestion)
        or (None, None)
    )
    visibility = contact_records[index]["contact_visibility"]
    if contact_records[index]["review_state"] != "confirmed" and suggestion:
        visibility = suggestion.get("contact_visibility") or visibility
    visibility_label = VISIBILITY_LABELS.get(visibility, VISIBILITY_LABELS["visible"])
    return (
        _editor_html(bbox_records, contact_records, state),
        state,
        _progress(bbox_records, contact_records, state),
        _instructions(state),
        message,
        index + 1,
        VIEW_LABELS[bbox_records[index]["view"]],
        *bbox_values,
        point[0],
        point[1],
        visibility_label,
    )


def on_load():
    state = initial_state()
    message = (
        "已进入数据集 V2 待标队列。黄色框和粉色点来自模型预标，"
        "可直接拖动或点击修正；模型建议不会自动写入正式标签。"
