    )


def navigate(state: dict[str, object], requested: int):
    bbox_records = load_bbox_records(PROJECT_ROOT)
    contact_records = contacts.load_records(PROJECT_ROOT)
    state = dict(state)
    index = max(0, min(len(bbox_records) - 1, int(requested)))
    if index not in _active_indices(bbox_records, state):
        return _outputs(
            bbox_records,
