def _event_payload(evt: gr.EventData) -> dict[str, object]:
    payload = getattr(evt, "_data", None)
    if isinstance(payload, dict) and isinstance(payload.get("data"), dict):
        payload = payload["data"]
    return payload if isinstance(payload, dict) else {}


def on_editor_apply(state: dict[str, object], evt: gr.EventData):
    bbox_records = load_bbox_records(PROJECT_ROOT)
    contact_records = contacts.load_records(PROJECT_ROOT)
    state = dict(state)
    payload = _event_payload(evt)
    action = payload.get("action")
    if action == "bbox":
        values = payload.get("bbox")
        if not isinstance(values, (list, tuple)) or len(values) != 4:
            return _outputs(bbox_records, contact_records, state, "未收到有效设备框坐标，请重试。")
        try:
            bbox = BBox(*values).normalized(*state["original_size"])
        except (TypeError, ValueError) as exc:
            return _outputs(bbox_records, contact_records, state, f"设备框无效：{exc}")
        state.update(mode="bbox", candidate_bbox=bbox.as_list(), first_corner=None)
        return _outputs(
            bbox_records,
            contact_records,
            state,
            "设备框已更新但尚未保存。可继续拖动角点、边线或框内区域微调。",
        )
    if action == "contact":
        point = payload.get("point")
        if not isinstance(point, (list, tuple)) or len(point) != 2:
            return _outputs(bbox_records, contact_records, state, "未收到有效接触点坐标，请重试。")
        ow, oh = state["original_size"]
        x = max(0, min(int(round(float(point[0]))), int(ow) - 1))
        y = max(0, min(int(round(float(point[1]))), int(oh) - 1))
        state.update(mode="contact", candidate_contact=[x, y])
        return _outputs(bbox_records, contact_records, state, f"已记录接触点 ({x}, {y})，确认后保存。")
    return _outputs(bbox_records, contact_records, state, "没有识别到画布操作，请重试。")

