    contacts.save_records(PROJECT_ROOT, contact_records)
    state.update(mode="bbox", first_corner=None, candidate_bbox=None, candidate_contact=None)
    return _outputs(bbox_records, contact_records, state, "当前 bbox 和接触标签已清空，原图未修改。")


def set_anchor(state: dict[str, object]):
    bbox_records = load_bbox_records(PROJECT_ROOT)
